schema.sdl:
type Query {
  viewer: User!
  named: Named!
  species(id: ID!): Species
  searched(term: String!): [Species!]!
  speciesList(first: Int, after: String, last: Int, before: String): SpeciesConnection!
  speciesFiltered(filter: SpeciesFilter!): [Species!]!
}

type Mutation {
  favorite(id: ID!): Species!
}

interface Named {
  display: String
}

type User implements Named {
  id: ID!
  name: String!
  display: String!
  favorite: Species
  power(level: Int): Int
}

type Species implements Named {
  id: ID!
  name: String!
  display: String
  move: SpeciesMove
  friends: [Species!]
  power(boost: Int): Int
}

type SpeciesMove {
  name: String!
  power: Int
}

type SpeciesConnection {
  edges: [SpeciesEdge!]!
  pageInfo: PageInfo!
}

type SpeciesEdge {
  node: Species!
  cursor: String!
}

type PageInfo {
  hasNextPage: Boolean!
  endCursor: String
}

input SpeciesFilter {
  term: String!
  limit: Int
}

inputs.text:
query DifferingArgs {
  species(id: "1") {
    id
  }
  species(id: "2") {
    id
  }
}

query ExclusiveArgs {
  named {
    ... on User {
      p: power(level: 1)
    }
    ... on Species {
      p: power(boost: 2)
    }
  }
}

query NestedSubfields {
  a: viewer {
    b: favorite {
      name
    }
  }
  a: viewer {
    b: favorite {
      name: id
    }
  }
}

query Overlap {
  species(id: "1") {
    name
    name: id
  }
}

query SameArgs {
  speciesFiltered(filter: { term: "a", limit: 1 }) {
    id
  }
  speciesFiltered(filter: { limit: 1, term: "a" }) {
    id
  }
}

query Skipped {
  species(id: "1") {
    id
  }
  species(id: "2") @skip(if: true) {
    id
  }
}

fragment SpreadB on User {
  name: id
}

fragment SpreadUser on User {
  name: id
}

query SubfieldConflict {
  a: viewer {
    name
  }
  a: viewer {
    name: id
  }
}

query TypeConflict {
  named {
    ... on Named {
      d: display
    }
    ... on User {
      d: display
    }
  }
}

query Typename {
  species(id: "1") {
    x: name
    x: __typename
  }
}
